VALUES ('article-lt-first-001', 'dovanos123', 'lt-LT', 'gift-casting-001', 'lt-hand-casting-guide-001', 'ranku-liejimo-rinkinys-kaip-pasiruosti', 'Rankų liejimo rinkinys: kaip pasiruošti pirmajam liejiniui', 'Praktinis gidas poroms: ką pasiruošti prieš rankų liejimą, kaip išvengti dažniausių klaidų ir ko tikėtis iš galutinio rezultato.', 'Personalizuotos dovanos', '[{"type":"paragraph","text":"Rankų liejimo rinkinys yra bendra patirtis, todėl geriausias rezultatas prasideda nuo ramaus pasiruošimo, o ne nuo skubėjimo."},{"type":"heading","level":2,"text":"Ką pasiruošti prieš pradedant"},{"type":"paragraph","text":"Pasirinkite stabilų stalą, pasiruoškite indą mišiniui, rankšluostį ir laikmatį. Prieš maišydami perskaitykite visą rinkinio instrukciją."},{"type":"heading","level":2,"text":"Kaip išvengti dažniausių klaidų"},{"type":"list","ordered":false,"items":["Neskubėkite maišydami formavimo mišinį.","Rankas laikykite ramiai visą nurodytą laiką.","Prieš išimdami liejinį palaukite, kol medžiaga sukietės."]},{"type":"product_cta","productId":"hand-casting-kit","label":"Peržiūrėti rankų liejimo rinkinį"}]', 'published', strftime('%s','2026-09-18 18:00:00') * 1000, 'version-lt-first-001', '["aiste-redaktore"]', '["source-hand-casting"]', unixepoch('now') * 1000, unixepoch('now') * 1000);
