VALUES ('article-lt-first-002', 'dovanos123', 'lt-LT', 'gift-couple-002', 'lt-gifts-for-couple-002', 'prasmingos-dovanos-porai-pagal-biudzeta', '9 prasmingos dovanos porai pagal biudžetą', 'Dovanų porai idėjos nuo mažo gesto iki bendros patirties: palyginame kainą, pasiruošimo laiką ir emocinę vertę.', 'Dovanos porai', '[{"type":"paragraph","text":"Gera dovana porai atsižvelgia į jų bendrą istoriją, o ne tik į progą kalendoriuje."},{"type":"heading","level":2,"text":"Iki 30 eurų"},{"type":"paragraph","text":"Mažesnio biudžeto dovana gali būti asmeniška: laiškas, bendra vakarienė namuose ar nedidelis daiktas su prasme."},{"type":"heading","level":2,"text":"Kai norisi bendros patirties"},{"type":"paragraph","text":"Rankų liejimo rinkinys leidžia dovaną sukurti kartu, todėl jo vertė yra ne tik galutiniame objekte, bet ir pačiame procese."}]', 'scheduled', strftime('%s','2026-09-19 04:00:00') * 1000, NULL, '["aiste-redaktore"]', '["source-gift-choice"]', unixepoch('now') * 1000, unixepoch('now') * 1000);
