VALUES ('article-lt-first-003', 'dovanos123', 'lt-LT', 'gift-anniversary-003', 'lt-anniversary-ideas-003', 'ka-dovanoti-vestuviu-metiniu-proga', 'Ką dovanoti vestuvių metinių proga? Atrankos kriterijai', 'Kaip išrinkti vestuvių metinių dovaną, kuri būtų asmeniška, praktiška ir atitiktų poros kasdienybę.', 'Dovanos progai', '[{"type":"paragraph","text":"Vestuvių metinių proga verta pradėti nuo poros įpročių, bendrų prisiminimų ir to, ką jie iš tikrųjų mėgsta veikti kartu."},{"type":"heading","level":2,"text":"Trys klausimai prieš renkant dovaną"},{"type":"list","ordered":true,"items":["Ar dovana sukuria bendrą momentą?","Ar ją bus patogu naudoti arba eksponuoti?","Ar ji atitinka šios poros istoriją?"]}]', 'review', NULL, NULL, '["aiste-redaktore"]', '["source-gift-choice"]', unixepoch('now') * 1000, unixepoch('now') * 1000);
